package com.huy.enterprise.inventory;
import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/inventory") @RequiredArgsConstructor public class InventoryController{private final InventoryService service;@GetMapping public List<InventoryResponse> all(){return service.all();}@GetMapping("/{id}") public InventoryResponse one(@PathVariable UUID id){return service.one(id);}@GetMapping("/low-stock") public List<InventoryResponse> lowStock(){return service.lowStock();}@PostMapping @ResponseStatus(HttpStatus.CREATED) public InventoryResponse create(@Valid @RequestBody InventoryRequest r){return service.create(r);}@PutMapping("/{id}") public InventoryResponse update(@PathVariable UUID id,@Valid @RequestBody InventoryRequest r){return service.update(id,r);}}
